// SPDX-License-Identifier: MIT
pragma solidity 0.6.12;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/ACRUX.sol";

contract PrivilegeEscalationTest is Test {
    ACRUX token;
    address owner;
    address attacker = address(0x1337);
    address marketingWallet = address(0x999);
    address charityWallet = address(0x888);

    address constant ROUTER_ADDRESS = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
    address constant WETH_ADDRESS = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
    address constant FACTORY_ADDRESS = address(0xA);
    address constant PAIR_ADDRESS = address(0xB);

    function setUp() public {
        // Set up mock Uniswap environment
        vm.mockCall(
            ROUTER_ADDRESS,
            abi.encodeWithSignature("factory()"),
            abi.encode(FACTORY_ADDRESS)
        );
        vm.mockCall(
            ROUTER_ADDRESS,
            abi.encodeWithSignature("WETH()"),
            abi.encode(WETH_ADDRESS)
        );
        vm.mockCall(
            FACTORY_ADDRESS,
            abi.encodeWithSignature("createPair(address,address)"),
            abi.encode(PAIR_ADDRESS)
        );

        owner = vm.addr(1);
        vm.startPrank(owner);
        token = new ACRUX(
            payable(marketingWallet),
            payable(charityWallet)
        );
        vm.stopPrank();
    }

    function testRepeatedLocking() public {
        // Owner locks contract
        vm.prank(owner);
        token.lock(1 days);

        // Validate lock was executed
        assertEq(token.owner(), address(0), "Owner not reset properly");

        // Warp to after lock period
        vm.warp(block.timestamp + 2 days);
        vm.prank(owner);  
        token.unlock();

        // Immediately relock after unlock
        vm.prank(owner);
        token.lock(1 days);

        // Verify contract locked again
        assertEq(token.owner(), address(0), "Re-lock failed");
    }

    function testTransferAndLock() public {
        // Transfer ownership to attacker
        vm.prank(owner);
        token.transferOwnership(attacker);

        // Become new owner
        vm.startPrank(attacker);
        token.lock(1 days);
        vm.stopPrank();

        // Validate lock executed
        assertEq(token.owner(), address(0), "Post-transfer lock failed");
    }
}
